163:         lookup::Gate::Unread => match host.db_key(&hash, &end_user).await? {
164:             Some(key) => (key, Shown::Stored(&hash)),
165:             None => return Err(Refused::new(crate::KeyDenial::NotFound { hash }, None)),
166:         },
167:     };
168:     expiry::usable(&key.record, request.now, shown, settings)
169:         .map_err(|denial| Refused::new(denial, Some(&key.row)))?;
170:     Ok(Verified::VirtualKey { key, end_user })
171: }

